/** Public job types, submission limits, and request validation shared by the server and worker. */

export const JOB_STATUSES = ['queued', 'running', 'completed', 'failed'] as const;
export type JobStatus = (typeof JOB_STATUSES)[number];

/** The JSON shape returned by every endpoint that describes a job. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

/** A validated submission, with defaults applied. */
export interface JobPayload {
  input: string;
  steps: number;
  failAttempts: number;
}

export interface FieldError {
  field: string;
  message: string;
}

export const DEFAULT_STEPS = 5;
export const DEFAULT_FAIL_ATTEMPTS = 0;
export const MIN_STEPS = 1;
export const MAX_STEPS = 20;
export const MIN_FAIL_ATTEMPTS = 0;
export const MAX_FAIL_ATTEMPTS = 5;
export const MAX_INPUT_LENGTH = 1000;
/** Total processing attempts before a job is marked failed. */
export const MAX_ATTEMPTS = 3;
export const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

/** True when the Content-Type header names application/json (any case, parameters allowed). */
export function isJsonContentType(header: string | undefined): boolean {
  if (typeof header !== 'string') return false;
  const mediaType = header.split(';')[0] ?? '';
  return mediaType.trim().toLowerCase() === 'application/json';
}

export type SubmissionResult = { ok: true; payload: JobPayload } | { ok: false; errors: FieldError[] };

/**
 * Validates a parsed request body. Every problem that can be attributed to a field is reported;
 * nothing is coerced. Defaults apply only when a field is absent.
 */
export function validateSubmission(value: unknown): SubmissionResult {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return { ok: false, errors: [{ field: 'body', message: 'Request body must be a JSON object.' }] };
  }
  const obj = value as Record<string, unknown>;
  const errors: FieldError[] = [];

  for (const key of Object.keys(obj)) {
    if (!ALLOWED_FIELDS.has(key)) errors.push({ field: key, message: 'Unknown field.' });
  }

  let input = '';
  if (!Object.hasOwn(obj, 'input')) {
    errors.push({ field: 'input', message: 'Field is required.' });
  } else {
    const raw = obj.input;
    if (typeof raw !== 'string') {
      errors.push({ field: 'input', message: 'Must be a string.' });
    } else if (raw.length < 1 || raw.length > MAX_INPUT_LENGTH) {
      errors.push({ field: 'input', message: `Must be 1 to ${MAX_INPUT_LENGTH} characters.` });
    } else if (raw.trim() === '') {
      errors.push({ field: 'input', message: 'Must not be only whitespace.' });
    } else {
      input = raw;
    }
  }

  const steps = integerField(obj, 'steps', DEFAULT_STEPS, MIN_STEPS, MAX_STEPS, errors);
  const failAttempts = integerField(obj, 'failAttempts', DEFAULT_FAIL_ATTEMPTS, MIN_FAIL_ATTEMPTS, MAX_FAIL_ATTEMPTS, errors);

  if (errors.length > 0) return { ok: false, errors };
  return { ok: true, payload: { input, steps, failAttempts } };
}

function integerField(
  obj: Record<string, unknown>,
  name: string,
  fallback: number,
  min: number,
  max: number,
  errors: FieldError[],
): number {
  if (!Object.hasOwn(obj, name)) return fallback;
  const raw = obj[name];
  if (typeof raw !== 'number' || !Number.isInteger(raw) || raw < min || raw > max) {
    errors.push({ field: name, message: `Must be an integer from ${min} to ${max}.` });
    return fallback;
  }
  return raw;
}

