import { DatabaseSync, type SQLInputValue, type StatementSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { dirname } from 'node:path';
import { MAX_ATTEMPTS, type Job, type JobPayload, type JobStatus } from './jobs.ts';

/** Opens the SQLite database shared by the server and worker processes. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  return db;
}

const SCHEMA = `
  CREATE TABLE IF NOT EXISTS jobs (
    seq INTEGER PRIMARY KEY AUTOINCREMENT,
    id TEXT NOT NULL UNIQUE,
    status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
    input TEXT NOT NULL,
    steps INTEGER NOT NULL,
    fail_attempts INTEGER NOT NULL,
    attempts INTEGER NOT NULL DEFAULT 0,
    completed_steps INTEGER NOT NULL DEFAULT 0,
    output TEXT,
    error TEXT,
    idempotency_key TEXT UNIQUE,
    available_at INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );
  CREATE INDEX IF NOT EXISTS jobs_queue ON jobs (status, available_at, seq);
  CREATE TABLE IF NOT EXISTS heartbeat (
    id INTEGER PRIMARY KEY CHECK (id = 1),
    pid INTEGER NOT NULL,
    at INTEGER NOT NULL
  );
`;

/** A row of the jobs table, as stored. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed_steps: number;
  output: string | null;
  error: string | null;
  idempotency_key: string | null;
  available_at: number;
  created_at: string;
  updated_at: string;
}

/** Converts a stored row to the public job shape. Internal columns never leave this function. */
export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed_steps, total: row.steps },
    result: row.status === 'completed' && row.output !== null ? { output: row.output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

/** Runs fn inside BEGIN IMMEDIATE ... COMMIT. fn must be synchronous. */
export function transaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  let result: T;
  try {
    result = fn();
    db.exec('COMMIT');
  } catch (err) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // the original error is more useful
    }
    throw err;
  }
  return result;
}

const iso = (ms: number): string => new Date(ms).toISOString();

export type CreateOutcome = { kind: 'created' | 'replayed'; row: JobRow } | { kind: 'conflict' };

/** Persistence operations shared by the server and the worker. */
export class JobStore {
  private readonly stmts: Record<string, StatementSync>;

  constructor(readonly db: DatabaseSync) {
    transaction(db, () => db.exec(SCHEMA));
    this.stmts = {
      byId: db.prepare('SELECT * FROM jobs WHERE id = ?'),
      byKey: db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?'),
      list: db.prepare('SELECT * FROM jobs ORDER BY seq DESC'),
      insert: db.prepare(
        `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed_steps, output, error,
                           idempotency_key, available_at, created_at, updated_at)
         VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, ?, ?, ?)`,
      ),
      nextQueued: db.prepare(
        `SELECT * FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq ASC LIMIT 1`,
      ),
      nextInterrupted: db.prepare(`SELECT * FROM jobs WHERE status = 'running' ORDER BY seq ASC LIMIT 1`),
      claim: db.prepare(
        `UPDATE jobs SET status = 'running', attempts = attempts + 1, completed_steps = 0,
                         output = NULL, error = NULL, updated_at = ?
         WHERE id = ? AND status = 'queued'`,
      ),
      resetInterrupted: db.prepare(
        `UPDATE jobs SET completed_steps = 0, output = NULL, error = NULL, updated_at = ?
         WHERE id = ? AND status = 'running'`,
      ),
      progress: db.prepare(
        `UPDATE jobs SET completed_steps = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
      ),
      complete: db.prepare(
        `UPDATE jobs SET status = 'completed', completed_steps = steps, output = ?, error = NULL, updated_at = ?
         WHERE id = ? AND status = 'running'`,
      ),
      fail: db.prepare(
        `UPDATE jobs SET status = 'failed', completed_steps = 0, output = NULL, error = 'transient failure', updated_at = ?
         WHERE id = ? AND status = 'running'`,
      ),
      requeue: db.prepare(
        `UPDATE jobs SET status = 'queued', completed_steps = 0, output = NULL, error = NULL,
                         available_at = ?, updated_at = ?
         WHERE id = ? AND status = 'running'`,
      ),
      heartbeat: db.prepare(
        `INSERT INTO heartbeat (id, pid, at) VALUES (1, ?, ?)
         ON CONFLICT (id) DO UPDATE SET pid = excluded.pid, at = excluded.at`,
      ),
      lastHeartbeat: db.prepare('SELECT at FROM heartbeat WHERE id = 1'),
      removeHeartbeat: db.prepare('DELETE FROM heartbeat WHERE id = 1'),
    };
  }

  private one(name: string, ...params: SQLInputValue[]): JobRow | undefined {
    return this.stmts[name]!.get(...params) as JobRow | undefined;
  }

  getRow(id: string): JobRow | undefined {
    return this.one('byId', id);
  }

  listRows(): JobRow[] {
    return this.stmts.list!.all() as unknown as JobRow[];
  }

  /**
   * Creates a queued job, or replays/conflicts with the job already stored under the idempotency
   * key. The lookup and insert share one transaction, so a key yields at most one job.
   */
  createOrReplay(payload: JobPayload, key: string | null, now: number): CreateOutcome {
    return transaction(this.db, (): CreateOutcome => {
      if (key !== null) {
        const existing = this.one('byKey', key);
        if (existing) {
          const same =
            existing.input === payload.input &&
            existing.steps === payload.steps &&
            existing.fail_attempts === payload.failAttempts;
          return same ? { kind: 'replayed', row: existing } : { kind: 'conflict' };
        }
      }
      const id = randomUUID();
      const ts = iso(now);
      this.stmts.insert!.run(id, payload.input, payload.steps, payload.failAttempts, key, now, ts, ts);
      return { kind: 'created', row: this.one('byId', id)! };
    });
