                         output = NULL, error = NULL, updated_at = ?
         WHERE id = ? AND status = 'queued'`,
      ),
      resetInterrupted: db.prepare(
        `UPDATE jobs SET completed_steps = 0, output = NULL, error = NULL, updated_at = ?
         WHERE id = ? AND status = 'running'`,
      ),
      progress: db.prepare(
        `UPDATE jobs SET completed_steps = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
      ),
      complete: db.prepare(
        `UPDATE jobs SET status = 'completed', completed_steps = steps, output = ?, error = NULL, updated_at = ?
         WHERE id = ? AND status = 'running'`,
      ),
      fail: db.prepare(
        `UPDATE jobs SET status = 'failed', completed_steps = 0, output = NULL, error = 'transient failure', updated_at = ?
         WHERE id = ? AND status = 'running'`,
      ),
      requeue: db.prepare(
        `UPDATE jobs SET status = 'queued', completed_steps = 0, output = NULL, error = NULL,
                         available_at = ?, updated_at = ?
         WHERE id = ? AND status = 'running'`,
      ),
      heartbeat: db.prepare(
        `INSERT INTO heartbeat (id, pid, at) VALUES (1, ?, ?)
         ON CONFLICT (id) DO UPDATE SET pid = excluded.pid, at = excluded.at`,
      ),
      lastHeartbeat: db.prepare('SELECT at FROM heartbeat WHERE id = 1'),
      removeHeartbeat: db.prepare('DELETE FROM heartbeat WHERE id = 1'),
    };
  }

  private one(name: string, ...params: SQLInputValue[]): JobRow | undefined {
    return this.stmts[name]!.get(...params) as JobRow | undefined;
  }

  getRow(id: string): JobRow | undefined {
    return this.one('byId', id);
  }

  listRows(): JobRow[] {
    return this.stmts.list!.all() as unknown as JobRow[];
  }

  /**
   * Creates a queued job, or replays/conflicts with the job already stored under the idempotency
   * key. The lookup and insert share one transaction, so a key yields at most one job.
   */
  createOrReplay(payload: JobPayload, key: string | null, now: number): CreateOutcome {
    return transaction(this.db, (): CreateOutcome => {
      if (key !== null) {
        const existing = this.one('byKey', key);
        if (existing) {
          const same =
            existing.input === payload.input &&
            existing.steps === payload.steps &&
            existing.fail_attempts === payload.failAttempts;
          return same ? { kind: 'replayed', row: existing } : { kind: 'conflict' };
        }
      }
      const id = randomUUID();
      const ts = iso(now);
      this.stmts.insert!.run(id, payload.input, payload.steps, payload.failAttempts, key, now, ts, ts);
      return { kind: 'created', row: this.one('byId', id)! };
    });
  }

  /** Returns a job left `running` by an interrupted worker, resetting its progress for replay. */
  claimInterrupted(now: number): JobRow | undefined {
    return transaction(this.db, () => {
      const row = this.one('nextInterrupted');
      if (!row) return undefined;
      this.stmts.resetInterrupted!.run(iso(now), row.id);
      return this.one('byId', row.id);
    });
  }

  /** Atomically claims the oldest eligible queued job for a new attempt. */
  claimNext(now: number): JobRow | undefined {
    return transaction(this.db, () => {
      const row = this.one('nextQueued', now);
      if (!row) return undefined;
      this.stmts.claim!.run(iso(now), row.id);
      return this.one('byId', row.id);
    });
  }

  setProgress(id: string, completed: number, now: number): void {
    transaction(this.db, () => this.stmts.progress!.run(completed, iso(now), id));
  }

  complete(id: string, output: string, now: number): void {
    transaction(this.db, () => this.stmts.complete!.run(output, iso(now), id));
  }

  fail(id: string, now: number): void {
    transaction(this.db, () => this.stmts.fail!.run(iso(now), id));
  }

  requeue(id: string, availableAt: number, now: number): void {
    transaction(this.db, () => this.stmts.requeue!.run(availableAt, iso(now), id));
  }

  heartbeat(now: number): void {
    this.stmts.heartbeat!.run(process.pid, now);
  }

  removeHeartbeat(): void {
    this.stmts.removeHeartbeat!.run();
  }

  /** Epoch milliseconds of the worker's last heartbeat, or undefined if none has been written. */
  lastHeartbeat(): number | undefined {
    const row = this.stmts.lastHeartbeat!.get() as { at: number } | undefined;
    return row?.at;
  }
}

