import { setTimeout as sleep } from 'node:timers/promises';
import { MAX_ATTEMPTS } from './jobs.ts';
import { JobStore, openDatabase, type JobRow } from './db.ts';

const STEP_MS = 100;
const POLL_MS = 100;
const HEARTBEAT_MS = 500;
const RETRY_DELAY_MS = 500;

const db = openDatabase();
const store = new JobStore(db);
let stopping = false;

function requestStop(): void {
  stopping = true;
}
process.on('SIGTERM', requestStop);
process.on('SIGINT', requestStop);

function logError(context: string, err: unknown): void {
  console.error(`worker: ${context}: ${err instanceof Error ? err.message : String(err)}`);
}

/**
 * Runs one attempt of a claimed job. Each durable transition is its own short transaction; no
 * transaction is held across the awaits. If stopping is requested, the attempt is abandoned with
 * the job still `running`, and startup recovery replays it later.
 */
async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  if (attempt <= job.fail_attempts) {
    // Simulated transient failure: fails at the first step, before any progress is recorded.
    await sleep(STEP_MS);
    if (stopping) return;
    const now = Date.now();
    if (attempt >= MAX_ATTEMPTS) store.fail(job.id, now);
    else store.requeue(job.id, now + RETRY_DELAY_MS, now);
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return;
    const now = Date.now();
    if (step === job.steps) store.complete(job.id, job.input.toUpperCase(), now);
    else store.setProgress(job.id, step, now);
  }
}

async function main(): Promise<void> {
  store.heartbeat(Date.now());
  const heartbeat = setInterval(() => {
    try {
      store.heartbeat(Date.now());
    } catch (err) {
      logError('heartbeat', err);
    }
  }, HEARTBEAT_MS);

  console.log('worker started');
  try {
    while (!stopping) {
      let job: JobRow | undefined;
      try {
        // Interrupted (running) jobs come first; they can only exist if a previous worker died.
        const now = Date.now();
        job = store.claimInterrupted(now) ?? store.claimNext(now);
      } catch (err) {
        logError('claim', err);
      }
      if (!job) {
        await sleep(POLL_MS);
        continue;
      }
      try {
        await runAttempt(job);
      } catch (err) {
        logError(`attempt on job ${job.id}`, err);
        await sleep(POLL_MS);
      }
    }
  } finally {
    clearInterval(heartbeat);
    try {
      store.removeHeartbeat();
    } catch (err) {
      logError('remove heartbeat', err);
    }
    db.close();
    console.log('worker stopped');
  }
}

main().catch((err: unknown) => {
  logError('fatal', err);
  process.exit(1);
});

