import { createServer, type IncomingMessage, type Server, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { JobStore, openDatabase, toJob } from './db.ts';
import {
  IDEMPOTENCY_KEY_PATTERN,
  isJsonContentType,
  validateSubmission,
  type FieldError,
  type JobPayload,
} from './jobs.ts';

const MAX_BODY_BYTES = 64 * 1024;
const HEARTBEAT_FRESH_MS = 3000;
const DRAIN_MS = 2000;
const HARD_EXIT_MS = 5000;

const db = openDatabase();
const store = new JobStore(db);
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
const port = Number(process.env.PORT ?? 3000);

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(
  res: ServerResponse,
  status: number,
  code: string,
  message: string,
  fields?: FieldError[],
  headers: Record<string, string> = {},
): void {
  sendJson(res, status, { error: fields ? { code, message, fields } : { code, message } }, headers);
}

function methodNotAllowed(res: ServerResponse, allowed: string): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed for this path.', undefined, { allow: allowed });
}

type BodyRead = { kind: 'ok'; text: string } | { kind: 'too-large' } | { kind: 'error' };

/** Reads the whole request body, enforcing a size limit and never throwing. */
function readBody(req: IncomingMessage): Promise<BodyRead> {
  return new Promise((resolve) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let settled = false;
    const settle = (result: BodyRead) => {
      if (!settled) {
        settled = true;
        resolve(result);
      }
    };
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        settle({ kind: 'too-large' });
        return;
      }
      if (!settled) chunks.push(chunk);
    });
    req.on('end', () => settle({ kind: 'ok', text: Buffer.concat(chunks).toString('utf8') }));
    req.on('error', () => settle({ kind: 'error' }));
    req.on('close', () => settle({ kind: 'error' }));
  });
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const errors: FieldError[] = [];

  let key: string | null = null;
  const keyHeader = req.headers['idempotency-key'];
  if (keyHeader !== undefined) {
    if (typeof keyHeader === 'string' && IDEMPOTENCY_KEY_PATTERN.test(keyHeader)) key = keyHeader;
    else errors.push({ field: 'Idempotency-Key', message: 'Must be 1 to 128 letters, digits, underscores, or hyphens.' });
  }

  const contentTypeOk = isJsonContentType(req.headers['content-type']);
  const body = await readBody(req);

  let payload: JobPayload | undefined;
  if (!contentTypeOk) {
    errors.push({ field: 'body', message: 'Content-Type must be application/json.' });
  } else if (body.kind === 'too-large') {
    errors.push({ field: 'body', message: `Body must be at most ${MAX_BODY_BYTES} bytes.` });
  } else if (body.kind === 'error') {
    errors.push({ field: 'body', message: 'Request body could not be read.' });
  } else {
    let parsed: unknown;
    let isJson = true;
    try {
      parsed = JSON.parse(body.text);
    } catch {
      isJson = false;
      errors.push({ field: 'body', message: 'Request body is not valid JSON.' });
    }
    if (isJson) {
      const result = validateSubmission(parsed);
      if (result.ok) payload = result.payload;
      else errors.push(...result.errors);
    }
  }

  if (errors.length > 0 || !payload) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', errors);
    return;
  }

  const outcome = store.createOrReplay(payload, key, Date.now());
  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  sendJson(res, outcome.kind === 'created' ? 201 : 200, toJob(outcome.row));
}

function workerIsUp(): boolean {
  const at = store.lastHeartbeat();
  return at !== undefined && Date.now() - at <= HEARTBEAT_FRESH_MS;
}

const JOB_PATH = /^\/api\/jobs\/([^/]+)$/;

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  // Route on the path only; the query string is ignored.
  const path = (req.url ?? '/').split('?')[0] ?? '/';
  const method = req.method ?? 'GET';

  if (path === '/') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (path === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    sendJson(res, 200, { status: 'ok', worker: workerIsUp() ? 'up' : 'down' });
    return;
  }

  if (path === '/api/jobs') {
    if (method === 'GET') {
      sendJson(res, 200, { jobs: store.listRows().map(toJob) });
      return;
    }
    if (method === 'POST') return createJob(req, res);
    return methodNotAllowed(res, 'GET, POST');
  }

  const match = JOB_PATH.exec(path);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    const row = store.getRow(match[1]!);
    if (!row) {
      sendError(res, 404, 'not_found', 'No job with that id.');
      return;
    }
    sendJson(res, 200, toJob(row));
    return;
  }

  sendError(res, 404, 'not_found', 'Not found.');
}

const server: Server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    console.error('server: request failed:', err);
    if (res.headersSent) res.end();
    else sendError(res, 500, 'internal_error', 'Internal server error.');
  });
});

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
  setTimeout(() => server.closeAllConnections(), DRAIN_MS).unref();
  setTimeout(() => {
    db.close();
    process.exit(0);
  }, HARD_EXIT_MS).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

server.listen(port, () => console.log(`server listening on ${port}`));

