mkdir -p "$TMPDIR/jt" && cat > "$TMPDIR/jt/verify.mjs" <<'EOF'
import { spawn } from 'node:child_process';
import { mkdtempSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

const REPO = process.argv[2];
const dir = mkdtempSync(join(process.env.TMPDIR ?? tmpdir(), 'jt-'));
const DB = join(dir, 'nested', 'jobs.db');
const PORT = 3900 + Math.floor(Math.random() * 500);
const env = { ...process.env, PORT: String(PORT), DATABASE_PATH: DB };
const base = `http://127.0.0.1:${PORT}`;
let procs = {};
let failures = 0;
const ok = (cond, msg) => { if (cond) console.log('ok  ', msg); else { failures++; console.log('FAIL', msg); } };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function start(name) {
  const p = spawn('node', ['--disable-warning=ExperimentalWarning', `dist/${name}.js`], { cwd: REPO, env, stdio: ['ignore', 'pipe', 'pipe'] });
  p.stderr.on('data', (d) => process.stdout.write(`[${name} stderr] ${d}`));
  procs[name] = p;
  return p;
}
function stop(name, sig = 'SIGTERM') { const p = procs[name]; if (p && p.exitCode === null && p.signalCode === null) p.kill(sig); }
const exited = (name) => new Promise((r) => { const p = procs[name]; if (!p || p.exitCode !== null || p.signalCode !== null) return r(); p.once('exit', (c, s) => r({ c, s })); });

async function req(method, path, body, headers = {}) {
  const res = await fetch(base + path, { method, headers: { ...(body !== undefined ? { 'content-type': 'application/json' } : {}), ...headers }, body: body === undefined ? undefined : (typeof body === 'string' ? body : JSON.stringify(body)) });
  const text = await res.text();
  let json; try { json = JSON.parse(text); } catch {}
  return { status: res.status, ct: res.headers.get('content-type'), json, text };
}
async function waitFor(id, pred, ms = 15000) {
  const end = Date.now() + ms;
  let j;
  while (Date.now() < end) { j = (await req('GET', `/api/jobs/${id}`)).json; if (pred(j)) return j; await sleep(50); }
  return j;
}
const fieldsOf = (r) => (r.json?.error?.fields ?? []).map((f) => f.field);

try {
  // Startup order: server first, worker later; health down before worker.
  start('server');
  await sleep(600);
  let h = await req('GET', '/health');
  ok(h.status === 200 && h.json.worker === 'down', `health down before worker: ${h.text}`);
  start('worker');
  await sleep(400);
  h = await req('GET', '/health');
  ok(h.json.worker === 'up', `health up with worker: ${h.text}`);

  // Validation
  const bad = [
    ['malformed', '{"input":', {}, 'body'],
    ['array', '[1]', {}, 'body'],
    ['null', 'null', {}, 'body'],
    ['scalar', '"x"', {}, 'body'],
  ];
  for (const [n, raw, _, f] of bad) {
    const r = await req('POST', '/api/jobs', raw, { 'content-type': 'application/json' });
    ok(r.status === 400 && r.json.error.code === 'invalid_request' && fieldsOf(r).includes(f), `${n} -> 400 ${f}`);
  }
  let r = await req('POST', '/api/jobs', '{"input":"a"}', {});
  ok(r.status === 400 && fieldsOf(r).includes('body'), 'missing content type -> 400 body');
  r = await req('POST', '/api/jobs', '{"input":"a"}', { 'content-type': 'Application/JSON; charset=utf-8' });
  ok(r.status === 201, 'content-type case/params accepted');
  r = await req('POST', '/api/jobs', { input: 'x', steps: '3', failAttempts: 1.5, colour: 'b' }, );
  ok(r.status === 400 && ['steps', 'failAttempts', 'colour'].every((f) => fieldsOf(r).includes(f)), `multiple fields reported: ${fieldsOf(r)}`);
  r = await req('POST', '/api/jobs', { input: '   ' });
  ok(r.status === 400 && fieldsOf(r).includes('input'), 'whitespace input rejected');
  r = await req('POST', '/api/jobs', { input: 'a'.repeat(1000), steps: 1 });
  ok(r.status === 201, '1000-char input accepted');
  r = await req('POST', '/api/jobs', { input: 'a'.repeat(1001) });
  ok(r.status === 400 && fieldsOf(r).includes('input'), '1001-char input rejected');
  r = await req('POST', '/api/jobs', { input: '😀'.repeat(500) });
  ok(r.status === 201, 'surrogate pairs counted by .length (500 emoji = 1000 units) accepted');
  r = await req('POST', '/api/jobs', { input: '😀'.repeat(501) });
  ok(r.status === 400, '501 emoji (1002 units) rejected');
  r = await req('POST', '/api/jobs', { input: 'x', steps: 0 });
  ok(r.status === 400 && fieldsOf(r).includes('steps'), 'steps 0 rejected');
  r = await req('POST', '/api/jobs', { input: 'x', steps: 21 });
  ok(r.status === 400, 'steps 21 rejected');
  r = await req('POST', '/api/jobs', { input: 'x', steps: null, failAttempts: null });
  ok(r.status === 400 && fieldsOf(r).includes('steps') && fieldsOf(r).includes('failAttempts'), 'null steps/failAttempts rejected');
  r = await req('POST', '/api/jobs', { input: 'x', failAttempts: 6 });
  ok(r.status === 400, 'failAttempts 6 rejected');
  r = await req('POST', '/api/jobs', { input: 'x' }, { 'idempotency-key': 'bad key!' });
  ok(r.status === 400 && fieldsOf(r).includes('Idempotency-Key'), 'bad idempotency key rejected');
  const before = (await req('GET', '/api/jobs')).json.jobs.length;
  r = await req('POST', '/api/jobs', { input: 'x', steps: 1.0 + 0 }, { 'idempotency-key': 'k' });
  ok(r.status === 201, 'steps 1.0 integer accepted');

  // Exact shape on creation
  r = await req('POST', '/api/jobs', { input: 'Shape check', steps: 2 });
  const shape = Object.keys(r.json).sort().join(',');
  ok(r.status === 201 && shape === 'attempts,createdAt,error,failAttempts,id,input,progress,result,status,steps,updatedAt', `exact shape keys: ${shape}`);
  ok(r.json.status === 'queued' && r.json.result === null && r.json.error === null, 'creation response queued');
  const shapeId = r.json.id;
  let done = await waitFor(shapeId, (j) => j.status === 'completed');
  ok(done.status === 'completed' && done.result.output === 'SHAPE CHECK' && done.progress.completed === 2 && done.attempts === 1, `completed shape: ${JSON.stringify(done)}`);

  // Unicode uppercase
  r = await req('POST', '/api/jobs', { input: 'straße ǆ', steps: 1 });
  done = await waitFor(r.json.id, (j) => j.status === 'completed');
  ok(done.result.output === 'STRASSE Ǆ'.replace('Ǆ', 'ǅ'.toUpperCase()), `unicode uppercase: ${done.result?.output}`);

  // Retries
  for (const fa of [0, 1, 2, 3, 5]) {
    r = await req('POST', '/api/jobs', { input: `retry${fa}`, steps: 2, failAttempts: fa });
    const t0 = Date.now();
    done = await waitFor(r.json.id, (j) => j.status === 'completed' || j.status === 'failed', 20000);
    const expectFail = fa >= 3;
    const expectAttempts = expectFail ? 3 : fa + 1;
    ok(done.status === (expectFail ? 'failed' : 'completed') && done.attempts === expectAttempts && (expectFail ? done.error === 'transient failure' && done.result === null && done.progress.completed === 0 : done.result.output === `RETRY${fa}`), `failAttempts ${fa}: status=${done.status} attempts=${done.attempts} progress=${done.progress.completed} elapsed=${Date.now() - t0}ms`);
  }

  // Ordering: newest-first listing, same-millisecond creation
  const ids = [];
  for (let i = 0; i < 5; i++) ids.push((await req('POST', '/api/jobs', { input: `ord${i}`, steps: 1 })).json.id);
  const list = (await req('GET', '/api/jobs')).json.jobs;
  ok(list[0].id === ids[4] && list.findIndex((j) => j.id === ids[0]) > list.findIndex((j) => j.id === ids[4]), 'listing newest first');

  // Idempotency
  const k = 'idem-' + Date.now();
  const [a, b] = await Promise.all([req('POST', '/api/jobs', { input: 'same' }, { 'idempotency-key': k }), req('POST', '/api/jobs', { input: 'same', steps: 5, failAttempts: 0 }, { 'idempotency-key': k })]);
  ok([a.status, b.status].sort().join() === '200,201' && a.json.id === b.json.id, `concurrent same-key: ${a.status},${b.status}`);
  r = await req('POST', '/api/jobs', { input: 'other' }, { 'idempotency-key': k });
  ok(r.status === 409 && r.json.error.code === 'idempotency_conflict', 'key conflict 409');
  const n1 = (await req('GET', '/api/jobs')).json.jobs.length;
  r = await req('POST', '/api/jobs', { input: 'nokey' });
  r = await req('POST', '/api/jobs', { input: 'nokey' });
  ok((await req('GET', '/api/jobs')).json.jobs.length === n1 + 2, 'keyless submissions always insert');

  // Routes
  ok((await req('GET', '/nope')).json.error.code === 'not_found', 'unknown path 404');
  ok((await req('GET', '/api/jobs/does-not-exist')).status === 404, 'missing id 404');
  r = await req('DELETE', '/api/jobs');
  ok(r.status === 405 && r.json.error.code === 'method_not_allowed' && r.ct.includes('application/json'), 'DELETE /api/jobs 405');
  r = await req('POST', '/health');
  ok(r.status === 405, 'POST /health 405');
  r = await req('POST', '/api/jobs/abc');
  ok(r.status === 405, 'POST /api/jobs/:id 405');
  r = await req('GET', '/');
  ok(r.status === 200 && r.ct.includes('text/html') && r.text.includes('data-testid="job-form"'), 'GET / serves UI');

  // Durability: SIGKILL the worker mid-progress with a 20-step job, then restart it
  r = await req('POST', '/api/jobs', { input: 'durable', steps: 20 });
  const durId = r.json.id;
  await waitFor(durId, (j) => j.progress.completed >= 3, 5000);
  stop('worker', 'SIGKILL'); await exited('worker');
  await sleep(3500);
  h = await req('GET', '/health');
  ok(h.json.worker === 'down', `health down after SIGKILL: ${h.text}`);
  const mid = (await req('GET', `/api/jobs/${durId}`)).json;
  console.log('     mid-kill state:', mid.status, mid.progress.completed, mid.attempts);
  start('worker');
  done = await waitFor(durId, (j) => j.status === 'completed' || j.status === 'failed', 12000);
  ok(done.status === 'completed' && done.result.output === 'DURABLE' && done.attempts === 1, `recovered after SIGKILL: ${done.status} attempts=${done.attempts}`);

  // Crash during the third (successful) attempt of failAttempts=2
  r = await req('POST', '/api/jobs', { input: 'third', steps: 20, failAttempts: 2 });
  const thirdId = r.json.id;
  await waitFor(thirdId, (j) => j.attempts === 3 && j.progress.completed >= 2, 15000);
  stop('worker', 'SIGKILL'); await exited('worker');
  start('worker');
  done = await waitFor(thirdId, (j) => j.status === 'completed' || j.status === 'failed', 12000);
  ok(done.status === 'completed' && done.attempts === 3 && done.result.output === 'THIRD', `recovered third attempt: ${done.status} attempts=${done.attempts}`);

  // Persistence across server restart
  const before2 = (await req('GET', '/api/jobs')).json.jobs.map((j) => j.id);
  stop('server'); const se = await exited('server');
  ok(se && se.s === null && se.c === 0, `server SIGTERM clean exit: ${JSON.stringify(se)}`);
  start('server'); await sleep(600);
  const after = (await req('GET', '/api/jobs')).json.jobs.map((j) => j.id);
  ok(before2.every((id) => after.includes(id)) && before2.length === after.length, 'job ids persist across server restart');
  r = await req('POST', '/api/jobs', { input: 'same' }, { 'idempotency-key': k });
  ok(r.status === 200 && r.json.id === a.json.id, 'idempotent replay after restart');

  // Shutdown of worker while idle and busy
  stop('worker'); const we = await exited('worker');
  ok(we && we.c === 0, `worker SIGTERM idle exit: ${JSON.stringify(we)}`);
  h = await req('GET', '/health');
  ok(h.json.worker === 'down', 'heartbeat removed on clean exit');
  start('worker');
  await sleep(300);
  r = await req('POST', '/api/jobs', { input: 'busy', steps: 20 });
  await waitFor(r.json.id, (j) => j.progress.completed >= 1, 5000);
  const t0 = Date.now();
  stop('worker'); const we2 = await exited('worker');
  ok(we2 && we2.c === 0 && Date.now() - t0 < 2000, `worker SIGTERM busy exit in ${Date.now() - t0}ms`);
} catch (e) {
  failures++; console.log('EXCEPTION', e);
} finally {
  for (const n of Object.keys(procs)) stop(n, 'SIGKILL');
  console.log(failures === 0 ? 'ALL OK' : `${failures} FAILURE(S)`);
  process.exit(failures ? 1 : 0);
}
EOF
cd "$TMPDIR/jt" && node verify.mjs "$(git -C "$OLDPWD" rev-parse --show-toplevel 2>/dev/null || echo "$OLDPWD")" 2>&1 | tail -120

